import { AvatarGroup, Button } from "march/ui"

// parti davetlileri: "Katıl" her basışta gruba bir kişi ekler; dört kişiden sonrası +N
const names = ["Elif", "Can", "Deniz", "Ada", "Mert", "Zeynep", "Kerem", "Selin"]

export function PartyGuests() {
  let $n = 3
  return <div sx={{ flex: ["row", "center"], gap: 3 }}>
    <AvatarGroup names={names.slice(0, $n)} max={4} size="md" />
    <Button size="sm" disabled={$n >= names.length} on:click={() => $n++}>Katıl</Button>
  </div>
}

import { AvatarGroup } from "march/ui"

// belgeyi görüntüleyenler: küçük, yan yana, sabit renk; +N balonu kendi metniyle
export function DocViewers() {
  return <div sx={{ flex: ["row", "center"], gap: 2 }}>
    <span sx={{ text: "sm", color: "muted" }}>Şu an bakıyor:</span>
    <AvatarGroup names={["Elif Arslan", "Can Demir", "Deniz Kaya", "Ada Yıldız", "Mert Öz", "Selin Ak"]} max={3} size="xs" spacing="gap"
      color="brand-blue" more={(rest: number) => <b>{`+${rest} kişi`}</b>} label={(n: number) => `${n} kişi bakıyor`} />
  </div>
}

import { AvatarGroup } from "march/ui"

// AvatarGroup'un özellikleri: names (ad ya da { name, src }), max, size, label (metin ya da işlev), more (false ya da
// kendi içeriğin), spacing, color, shape, class
export function AvatarGroupLab() {
  return <div sx={{ flex: "col", gap: 3 }}>
    <AvatarGroup class="lab-more" names={["A B", "C D", "E F", "G H", "I J"]} max={2} label="Ekip" />
    <AvatarGroup class="lab-nomore" names={["A B", "C D", "E F"]} max={1} more={false} shape="square" size="lg" color="neutral" />
    <AvatarGroup class="lab-gap" names={[{ name: "Deniz", src: "/media/social/sea.svg" }, "Elif"]} spacing="gap" />
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { AvatarGroupLab } from "./AvatarGroupLab.tsx"

// AvatarGroupLab'in testleri: kaydedince Testler sekmesinde çalışır
test("max'tan fazlası +N balonunda", () => {
  const s = renderTest(() => <AvatarGroupLab />)
  expect(s.get(".lab-more")?.textContent).toContain("+3")
  expect(s.get(".lab-more")?.getAttribute("aria-label")).toBe("Ekip")
})

test("more={false} balonu kaldırır", () => {
  const s = renderTest(() => <AvatarGroupLab />)
  expect(s.get(".lab-nomore")?.textContent).not.toContain("+")
})
